import React, { useState } from 'react';
import { getAllExamCounts } from '../services/api';  // Import the getAllExamCounts function

const ExamDataCount = ({ franchiseId }) => {
    const [period, setPeriod] = useState('month'); // Default period
    const [examDataCount, setExamDataCount] = useState(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    // Function to fetch exam data count using getAllExamCounts
    const fetchExamDataCount = async () => {
        setLoading(true);
        setError('');
        try {
            const response = await getAllExamCounts(franchiseId, period);
            setExamDataCount(response);  // Assuming the response is the data containing the counts
        } catch (err) {
            console.error(err);
            setError('An error occurred while fetching data.');
        } finally {
            setLoading(false);
        }
    };

    // Handler for period change
    const handlePeriodChange = (e) => {
        setPeriod(e.target.value);
    };

    return (
        <div>
            <h2>Exam Data Count for Franchise {franchiseId}</h2>

            <div>
                <label htmlFor="period">Select Period: </label>
                <select id="period" value={period} onChange={handlePeriodChange}>
                    <option value="month">This Month</option>
                    <option value="week">This Week</option>
                    <option value="day">Today</option>
                </select>
            </div>

            <button onClick={fetchExamDataCount} disabled={loading}>
                {loading ? 'Loading...' : 'Get Exam Data Count'}
            </button>

            {error && <p style={{ color: 'red' }}>{error}</p>}

            {examDataCount !== null && !loading && (
                <div>
                    {/* Show the total exams count */}
                    <h3>Total Exams: {examDataCount.totalExams}</h3>

                    {/* Show the exam data based on selected period */}
                    {period === 'day' && <h3>Exams Today: {examDataCount.examsByDay}</h3>}
                    {period === 'week' && <h3>Exams This Week: {examDataCount.examsByWeek}</h3>}
                    {period === 'month' && <h3>Exams This Month: {examDataCount.examsByMonth}</h3>}

                    {/* Show the total exam count for each period */}
                    <div>
                        <h3>Total Exams Today: {examDataCount.examsByDay}</h3>
                        <h3>Total Exams This Week: {examDataCount.examsByWeek}</h3>
                        <h3>Total Exams This Month: {examDataCount.examsByMonth}</h3>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ExamDataCount;
